// ----------------------------------------------------------------------------------------------
var particles = []
var colors = []
var directions = []
var speed = 0.4
const defaultPreferences = {
  numParticles: numParticles,
	colors: themes.blue,
  numDirections: 1,
  resetCriteria: {
    age: {
      min: 50,
      max: 300
    }
  }
}
const settings = {...defaultPreferences, ...userPreferences}

// ----------------------------------------------------------------------------------------------
function setup() {
  createCanvas(windowWidth, windowHeight)
  noStroke()
  directions = createDirections(settings.numDirections)
  colors = createColors(settings.colors)
  particles = createParticles(settings.numParticles, colors)
	speed = determineSpeed(maxSpeed)
}

function draw() {
  smooth()
  fill(0, 7)
  noStroke()
  rect(0, 0, width, height)

  for (let id=0; id<particles.length; id++) {
    const radius = map(id, 0, particles.length/colors.length, 3, 5)
    for(let c=0; c<colors.length; c++) {
      const particleId = id + c
      if (!particles[particleId]) {
        continue
      }
      const particle = particles[particleId]
			// Draw particle
      fill(colors[c])
      particle.update(radius, noiseStrength/100, noiseScale, speed)
    }
  }   
}

function createParticles(expectedNumParticles, colorsArray) {
	newParticles = []
	for (let i=0; i<expectedNumParticles; i++) {
    // One particle for evey color
    for (let c in colors) {
      newParticles.push(new Particle(random(directions), settings.resetCriteria.age))
    }
  }

	return newParticles
}

function determineSpeed(maximumSpeed, speedVariationPercentage=20) {
	return random(
		(maximumSpeed - ((maximumSpeed*speedVariationPercentage)/100))/1000,
		maximumSpeed/1000
	)
}

function createColors(palette) {
	newColors = []
	for (let c in palette) {
		const newColor = color(...palette[c])
		newColors.push(newColor)
	}
	return newColors
}

function createDirections(numDirections) {
	const newDirections = []
	for (let i=0; i<numDirections; i++) {
    const angle = random(TWO_PI)
    const direction = createVector(cos(angle), sin(angle))
    newDirections.push(direction)
  }
	return newDirections
}

function parameterChanged(variableName, value) {
	switch (variableName) {
		case 'numParticles':
			particles = createParticles(numParticles, colors)
			break;
		case 'maxSpeed':
		case 'varSpeed':
			speed = determineSpeed(maxSpeed)
			break
	}
}

// === Tab: Particle ===
class Particle {
	constructor(directionVector, ageConstraints) {
		this.direction = directionVector
		this.diesAtAge = random(ageConstraints.min, ageConstraints.max)
		this.location = this.createStartingPoint()
		this.reset()
	}

	update(radius, strength, scale, speed) {
		this.drawParticle(radius, strength, scale, speed)
		this.moveInsideWhenOutOfBounds()
		this.age++
	}

	createStartingPoint() {
		return createVector(random(width*1.2), random(height), 2)
	}

	reset() {
		this.location = this.createStartingPoint()
		this.age = 1
	}

	moveInsideWhenOutOfBounds() {
		if (this.location.x < 0 || this.location.x > width) {
			return this.reset()
		}
		if (this.location.y < 0 || this.location.y > height) {
			return this.reset()
		}
		if (this.age > this.diesAtAge) {
			return this.reset()
		}
	}

	drawParticle(radius, strength, scale, speed) {
		var angle=noise(this.location.x/scale, this.location.y/scale, frameCount/scale) * TWO_PI * strength
		this.direction.x = cos(angle) + sin(angle) - sin(angle)
		this.direction.y = sin(angle) - cos(angle) * sin(angle)

		const distance = 1.4
		const velocity = this.direction.copy()
		velocity.mult(speed * distance)
		this.location.add(velocity)

		ellipse(this.location.x, this.location.y, radius);
	}
}

